/**
 * FeltDB Protocol - Low-level communication protocol
 */
export class ProtocolHandler {
    static encode(message) {
        return JSON.stringify(message);
    }
    static decode(data) {
        return JSON.parse(data);
    }
    static createOperation(op) {
        return {
            type: 'operation',
            payload: op,
            id: `op-${Date.now()}`,
        };
    }
}
